-- FORNEXA — MUELLES-V1 Synthetic Production Seed Loader
-- Batch ID: MUELLES-SEED-PRODUCTION-20261017
-- Tenant ID: 00000000-0000-4000-8000-000000000001
-- Constraint: Zero mutations to pre-existing rows, dynamic OWNER/ADMIN actor resolution, fail-closed
BEGIN;

DO $$
DECLARE
  v_owner uuid;
BEGIN
  SELECT tm.user_id INTO v_owner FROM public.tenant_members tm JOIN auth.users u ON u.id = tm.user_id WHERE tm.tenant_id = '00000000-0000-4000-8000-000000000001' AND tm.status = 'ACTIVE' AND tm.role IN ('OWNER', 'ADMIN') ORDER BY CASE tm.role WHEN 'OWNER' THEN 1 ELSE 2 END, tm.created_at ASC LIMIT 1;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'MUELLES_SEED_PREFLIGHT_FAILED: No active OWNER/ADMIN found for tenant';
  END IF;
END $$;

